   103	        if (!policies || isEmptyObject(policies)) {
   104	            return [];
   105	        }
   106	
   107	        return Object.values(policies)
   108	            .filter((policy) => PolicyUtils.shouldShowPolicy(policy, !!isOffline, currentUserLogin) && !policy?.isJoinRequestPending)
   109	            .map((policy) => ({
   110	                text: policy?.name ?? '',
   111	                policyID: policy?.id ?? '-1',
   112	                brickRoadIndicator: getIndicatorTypeForPolicy(policy?.id),
   113	                icons: [
   114	                    {
   115	                        source: policy?.avatarURL ? policy.avatarURL : ReportUtils.getDefaultWorkspaceAvatar(policy?.name),
   116	                        fallbackIcon: Expensicons.FallbackWorkspaceAvatar,
   117	                        name: policy?.name,
   118	                        type: CONST.ICON_TYPE_WORKSPACE,
   119	                        id: policy?.id,
   120	                    },
   121	                ],
   122	                isBold: hasUnreadData(policy?.id),
   123	                keyForList: policy?.id,
   124	                isPolicyAdmin: PolicyUtils.isPolicyAdmin(policy),
   125	                isSelected: activeWorkspaceID === policy?.id,
   126	            }));
   127	    }, [policies, isOffline, currentUserLogin, getIndicatorTypeForPolicy, hasUnreadData, activeWorkspaceID]);
   128	
   129	    const filteredAndSortedUserWorkspaces = useMemo<WorkspaceListItem[]>(
   130	        () =>
   131	            usersWorkspaces
   132	                .filter((policy) => policy.text?.toLowerCase().includes(debouncedSearchTerm?.toLowerCase() ?? ''))
   133	                .sort((policy1, policy2) => sortWorkspacesBySelected({policyID: policy1.policyID, name: policy1.text}, {policyID: policy2.policyID, name: policy2.text}, activeWorkspaceID)),
   134	        [debouncedSearchTerm, usersWorkspaces, activeWorkspaceID],
   135	    );
   136	
   137	    const sections = useMemo(() => {
   138	        const options: Array<SectionListDataType<WorkspaceListItem>> = [
   139	            {
   140	                data: filteredAndSortedUserWorkspaces,
   141	                shouldShow: true,
   142	                indexOffset: 1,
   143	            },
   144	        ];
   145	        return options;
   146	    }, [filteredAndSortedUserWorkspaces]);
   147	
   148	    const headerMessage = filteredAndSortedUserWorkspaces.length === 0 && usersWorkspaces.length ? translate('common.noResultsFound') : '';
   149	    const shouldShowCreateWorkspace = usersWorkspaces.length === 0;
   150	
   151	    const defaultPolicy = {
   152	        text: CONST.WORKSPACE_SWITCHER.NAME,
   153	        icons: [{source: Expensicons.ExpensifyAppIcon, name: CONST.WORKSPACE_SWITCHER.NAME, type: CONST.ICON_TYPE_AVATAR}],
   154	        brickRoadIndicator: getIndicatorTypeForPolicy(undefined),
   155	        keyForList: CONST.WORKSPACE_SWITCHER.NAME,
   156	        isSelected: activeWorkspaceID === undefined,
   157	    };
   158	
   159	    return (
   160	        <ScreenWrapper
   161	            testID={WorkspaceSwitcherPage.displayName}
   162	            includeSafeAreaPaddingBottom={false}
   163	        >
   164	            {({didScreenTransitionEnd}) => (
   165	                <>
   166	                    <HeaderWithBackButton
   167	                        title={translate('workspace.switcher.headerTitle')}
   168	                        onBackButtonPress={Navigation.goBack}
   169	                    />
   170	                    <View style={[styles.ph5, styles.flexRow, styles.justifyContentBetween, styles.alignItemsCenter, styles.mb1]}>
   171	                        <Text
   172	                            style={styles.label}
   173	                            color={theme.textSupporting}
   174	                        >
   175	                            {translate('workspace.switcher.everythingSection')}
   176	                        </Text>
   177	                    </View>
   178	                    <UserListItem
   179	                        item={defaultPolicy}
   180	                        isFocused={activeWorkspaceID === undefined}
   181	                        showTooltip={false}
   182	                        onSelectRow={() => selectPolicy(defaultPolicy)}
   183	                        pressableStyle={styles.flexRow}
   184	                        shouldSyncFocus={false}
   185	                    />
   186	                    <WorkspacesSectionHeader />
   187	                    <SelectionList<WorkspaceListItem>
