   189	                        sections={sections}
   190	                        onSelectRow={selectPolicy}
   191	                        textInputLabel={usersWorkspaces.length >= CONST.WORKSPACE_SWITCHER.MINIMUM_WORKSPACES_TO_SHOW_SEARCH ? translate('common.search') : undefined}
   192	                        textInputValue={searchTerm}
   193	                        onChangeText={setSearchTerm}
   194	                        headerMessage={headerMessage}
   195	                        listEmptyContent={WorkspaceCardCreateAWorkspaceInstance}
   196	                        shouldShowListEmptyContent={shouldShowCreateWorkspace}
   197	                        initiallyFocusedOptionKey={activeWorkspaceID ?? CONST.WORKSPACE_SWITCHER.NAME}
   198	                        showLoadingPlaceholder={fetchStatus.status === 'loading' || !didScreenTransitionEnd}
   199	                    />
   200	                </>
   201	            )}
   202	        </ScreenWrapper>
   203	    );
